pub fn table_recipe_guide_units(game: &mut crate::game::Game<'_>, stacks: &[Option<horizon_client::items::ItemStack>]) -> Vec<Option<horizon_client::items::ItemStack>> {
    let mut result: Vec<Option<horizon_client::items::ItemStack>> = Vec::new();
    for stack in stacks.iter() {
        {
            let mut i: i32 = 0;
            while i < ((9i32).min(stack.as_ref().map_or(0, |s| s.count as i32))) {
                result.push(stack.clone());
                i += 1;
            }
        }
    }
    return result.to_vec();
}

